// Types of the account area: the signed-in user on Astro.locals (src/middleware.ts).
// Cloudflare bindings (DB, FILES, ADMIN_EMAILS) come from worker-configuration.d.ts,
// generated by `npx wrangler types` (rerun after changing wrangler.jsonc).
declare namespace App {
  interface Locals {
    user: import('./lib/server/auth').User | null;
  }
}
